import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import test from "node:test";
import { Compile } from "typebox/compile";
import {
  analysisPeriodRequestBody,
  callsignFrequencyMatchesRequestBody,
  dailyActivityRequestBody,
  directionFindingsRequestBody,
  frequencySummaryRequestBody,
  inboxMessagesRequestBody,
  interceptionContextRequestBody,
  messagesByIdRequestBody,
  positionLookupRequestBody,
  unitLookupRequestBody,
} from "./runner.ts";

// Echo's request types, generated by `just gen-ai-agent-schemas`. A Rust change
// that renames or removes a field the runner sends fails here, not in production.
const SCHEMAS: Record<string, object> = JSON.parse(
  readFileSync(
    process.env.ECHO_AI_AGENT_REQUEST_SCHEMAS ?? new URL("../../wdintel-rs/src/ai_agent/request_schemas.json", import.meta.url),
    "utf8",
  ),
);

const context = {
  timeZone: "Europe/Kyiv" as const,
  requestStartedAtUtc: "2026-11-11T06:00:00.000Z",
  requestStartedAtMs: Date.parse("2026-11-11T06:00:00.000Z"),
};
const period = { kind: "date_range", sinceDate: "2026-11-01", tillDateInclusive: "2026-11-07" };
const filters = {
  selectedGroups: ["group.devops"],
  selectedCallsigns: ["Сокіл"],
  selectedFrequencies: ["163.9350"],
  selectedUnitIds: [7],
  selectedUnits: ["8 дшр"],
};

// Each builder with every argument it accepts, so every body field it can send is checked.
const BODIES: [skill: string, body: () => unknown][] = [
  ["inbox_messages", () => inboxMessagesRequestBody({ period, search: "Сокіл", maxItems: 20, ...filters }, context)],
  ["inbox_messages", () => inboxMessagesRequestBody({ period: { kind: "relative_hours", hours: 24 } }, context)],
  ["direction_findings", () => directionFindingsRequestBody({ period, selectedGroups: filters.selectedGroups }, context)],
  ["frequency_summary", () => frequencySummaryRequestBody({ period, ...filters }, context)],
  ["new_callsigns", () => analysisPeriodRequestBody({ period, selectedGroups: filters.selectedGroups }, context, 366, "new callsigns")],
  ["daily_activity", () => dailyActivityRequestBody({ period, selectedGroups: filters.selectedGroups }, context)],
  ["callsign_relations", () => analysisPeriodRequestBody({ period, selectedGroups: filters.selectedGroups }, context, 31, "callsign relations")],
  ["callsign_frequency_matches", () => callsignFrequencyMatchesRequestBody({ period, selectedGroups: filters.selectedGroups, callsigns: ["Сокіл", "Беркут"], minMatches: 2, maxItems: 10 }, context)],
  ["messages_by_id", () => messagesByIdRequestBody({ messageIds: [42, 43] })],
  ["interception_context", () => interceptionContextRequestBody({ messageUid: "message-42" })],
  ["position_lookup", () => positionLookupRequestBody({ name: "Глибоке", days: 7 })],
  ["position_lookup", () => positionLookupRequestBody({ coordinates: "50.1, 36.2", radiusMeters: 500 })],
  ["unit_lookup", () => unitLookupRequestBody({ query: "8 дшр", includeInactive: true })],
];

test("#4125 every request builder sends what Echo's request type declares", () => {
  for (const [skill, build] of BODIES) {
    const schema = SCHEMAS[skill];
    assert.ok(schema, `no generated schema for ${skill}`);
    const body = build();
    const validator = Compile(schema as any);
    const errors = [...validator.Errors(body)].map((error: any) => `${error.instancePath || "/"} ${error.message}`);
    assert.deepEqual(errors, [], `${skill} body ${JSON.stringify(body)} breaks Echo's request type`);
  }
});

test("#4125 the contract check catches a renamed field", () => {
  const validator = Compile(SCHEMAS.messages_by_id as any);
  assert.ok(validator.Check({ message_ids: [42] }));
  assert.ok(!validator.Check({ messageIds: [42] }));
  assert.ok(!validator.Check({ message_ids: [42], inbox_req: {} }));
});
